<?php
namespace App\Console\Commands; use Illuminate\Console\Command; use Illuminate\Support\Facades\Route; use Illuminate\Support\Facades\Schema;
class WarehouseV2PurchasingCheckCommand extends Command{protected $signature='warehouse:v2-purchasing-check';protected $description='Smoke check Purchasing Warehouse v2';public function handle():int{$tables=['wh_supplier_invoices','wh_supplier_invoice_items','wh_landed_costs','wh_supplier_payments','wh_supplier_payment_allocations','wh_purchasing_events'];$missing=array_values(array_filter($tables,fn($t)=>!Schema::hasTable($t)));$routes=['api/v1/warehouse/purchasing-finance/dashboard','api/v1/warehouse/purchasing-finance/supplier-invoices','api/v1/warehouse/purchasing-finance/supplier-payments'];$uris=collect(Route::getRoutes())->map(fn($r)=>$r->uri());$mr=array_values(array_filter($routes,fn($r)=>!$uris->contains($r)));$this->table(['Check','Result'],[['Missing tables',$missing?implode(', ',$missing):'-'],['Missing routes',$mr?implode(', ',$mr):'-'],['Status',(!$missing&&!$mr)?'PASSED':'FAILED']]);return(!$missing&&!$mr)?self::SUCCESS:self::FAILURE;}}
